-- Baseline MVP schema. Apply with Supabase CLI before configuring the client.
create extension if not exists pgcrypto;
create type public.room_kind as enum ('world','country','interest','custom');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, username text unique not null check (username ~ '^[a-zA-Z0-9_]{3,32}$'), country_code text check(country_code ~ '^[A-Z]{2}$'), created_at timestamptz not null default now());
create table public.rooms (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, topic text, kind public.room_kind not null, is_private boolean not null default false, created_by uuid references public.profiles(id), created_at timestamptz not null default now());
create table public.room_members (room_id uuid references public.rooms(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, role text not null default 'member' check(role in ('owner','moderator','member')), joined_at timestamptz not null default now(), primary key(room_id,user_id));
create table public.messages (id uuid primary key default gen_random_uuid(), room_id uuid not null references public.rooms(id) on delete cascade, sender_id uuid not null references public.profiles(id) on delete cascade, body text not null check(char_length(body) between 1 and 4000), created_at timestamptz not null default now(), edited_at timestamptz, deleted_at timestamptz);
alter table public.profiles enable row level security; alter table public.rooms enable row level security; alter table public.room_members enable row level security; alter table public.messages enable row level security;
create policy "profiles readable to signed-in users" on public.profiles for select to authenticated using (true);
create policy "users update own profile" on public.profiles for update to authenticated using (id=auth.uid()) with check(id=auth.uid());
create policy "visible rooms only" on public.rooms for select to authenticated using (not is_private or exists(select 1 from public.room_members m where m.room_id=id and m.user_id=auth.uid()));
create policy "members can read membership" on public.room_members for select to authenticated using (exists(select 1 from public.room_members mine where mine.room_id=room_id and mine.user_id=auth.uid()));
create policy "visible messages only" on public.messages for select to authenticated using (exists(select 1 from public.rooms r where r.id=room_id and (not r.is_private or exists(select 1 from public.room_members m where m.room_id=room_id and m.user_id=auth.uid()))));
create policy "members send as self" on public.messages for insert to authenticated with check(sender_id=auth.uid() and exists(select 1 from public.rooms r where r.id=room_id and (not r.is_private or exists(select 1 from public.room_members m where m.room_id=room_id and m.user_id=auth.uid()))));
create policy "authors edit own messages" on public.messages for update to authenticated using(sender_id=auth.uid()) with check(sender_id=auth.uid());
create policy "authors delete own messages" on public.messages for delete to authenticated using(sender_id=auth.uid());
alter publication supabase_realtime add table public.messages;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,username) values(new.id, coalesce(nullif(new.raw_user_meta_data->>'username',''), 'member_' || substr(new.id::text,1,8))); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
insert into public.rooms(slug,name,topic,kind,is_private) values ('world','World','The global public room.','world',false),('cybersecurity','Cybersecurity','Defensive learning and responsible research.','interest',false),('linux','Linux','Systems, distributions, and command lines.','interest',false),('programming','Programming','Build, debug, and exchange ideas.','interest',false),('ai','AI','Models, tools, and careful discussion.','interest',false),('ctf','CTF','Practice, write-ups, and learning.','interest',false),('science','Science','Evidence-led curiosity.','interest',false),('hardware','Hardware','Bits, boards, and repair.','interest',false) on conflict(slug) do nothing;
